-- 73 코스모스 → 코스모스 (사이언스북스)
UPDATE work SET release_date = DATE '2006-12-20', summary = '전 세계 60개국에 방송되어 6억 시청자를 감동시킨 텔레비전 교양 프로그램을 책으로 옮긴 칼 세이건(Carl Sagan)의 『코스모스(Cosmos)』. 현대 천문학을 대표하는 저명한 과학자인 칼 세이건은 이 책에서 사람들의 상상력을 사로잡고, 난해한 개념을 명쾌하게 해설하는 놀라운 능력을 마음껏 발휘한다. 그는 에라토스테네스, 데모크리토스, 히파티아, 케플러, 갈릴레오, 뉴턴, 다윈 같은 과학의 탐험가들이 개척해 놓은 길을 따라가며 과거, 현재, 미래의 과학이 이뤘고, 이루고 있으며, 앞으로 이룰 성과들을 알기 쉽게 풀이해 들려준?..', poster_url = 'https://image.yes24.com/goods/2312211/L', source = 'YES24', external_id = '2312211' WHERE work_id = 73 AND type = 'BOOK' AND (source IS NULL OR source = 'YES24');
