-- 74 이기적 유전자 → 이기적 유전자 (을유문화사)
UPDATE work SET release_date = DATE '2010-08-10', summary = '진화생물학 분야의 과학자치고 리처드 도킨스만큼 대중적 인기와 학술적 논쟁을 결합시킨 사람도 흔치 않다. 그는 일찍이 촉망받는 젊은 동물행동학자로 간결한 문체와 생생한 비유, 논리적인 전개를 갖춘 글로 능력을 인정받아 왔다. 도킨스는 자신의 동물행동학 연구를 유전자가 진화의 역사에서 차지하는 중심적 역할에 대한 좀더 넓은 이론적 맥락과 연결시키기 시작했는데, 그 결과가 바로 『이기적 유전자』(1976)이다.', poster_url = 'https://image.yes24.com/goods/4078717/L', source = 'YES24', external_id = '4078717' WHERE work_id = 74 AND type = 'BOOK' AND (source IS NULL OR source = 'YES24');
