UPDATE work SET release_date = DATE '2019-02-26', summary = '고교 시절 촉망받는 야구선수였던 제임스 클리어는 연습 중 동료의 야구 배트에 얼굴을 정통으로 강타당하는 큰 사고를 당했다. 이 사고로 얼굴 뼈가 30조각이 났고, 왼쪽 눈이 튀어나와 실명 위기까지 왔으며, 심정지가 세 번이나 일어났다. 걸을 수조차 없었던 그는 절망에 빠지는 대신 지금 당장 할 수 있는 아주 작은 일이라도 찾아 그것을 반복하자고 마음먹는다. 그 후 매일 걷기 연습을 해서 6개월 만에 운동을 할 수 있게 되었고, 6년 후에는 대학 최고 남자 선수가 되었다. 이 경험을 바탕으로 그는 자신을 인생의 나락에서 구해준 ‘아주 작은 습관의 힘’을 전 세계에 알리는 최고의 자기계발 전문가가 되었다.', poster_url = 'https://image.yes24.com/goods/69655504/L', source = 'YES24', external_id = '69655504' WHERE work_id = 79 AND type = 'BOOK' AND (source IS NULL OR source = 'YES24');
UPDATE book SET isbn = '9791162540640', pages = 360 WHERE work_id = 79;
