UPDATE work SET release_date = DATE '2016-08-19', summary = '언어에는 나름의 온도가 있다고 생각하는 저자가 일상에서 발견한 의미 있는 말과 글을 한 권의 책에 담았다. 저자는 단어의 어원과 유래, 그런 언어가 지닌 차가움과 따뜻함을 글감 삼아, 하찮아 보이는 것들의 소중함을 예찬한다. 페이지를 넘길 때마다 문장과 문장에 호흡을 불어넣으며 뜨거운 음식을 먹듯 찬찬히 곱씹어 읽다 보면, 독자 스스로 각자의 ‘언어 온도’를 되짚어볼 수 있을지 모른다.', poster_url = 'https://image.yes24.com/goods/30387696/L', source = 'YES24', external_id = '30387696' WHERE work_id = 80 AND type = 'BOOK' AND (source IS NULL OR source = 'YES24');
